import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.B8xISX-C.js";const p=JSON.parse('{"title":"tech-fields","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tech-fields.md","filePath":"reference/tech-fields.md"}'),c={name:"reference/tech-fields.md"};function i(s,e,r,l,n,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tech-fields" tabindex="-1">tech-fields <a class="header-anchor" href="#tech-fields" aria-label="Permalink to &quot;tech-fields&quot;">​</a></h1><p>A research field: one step of one of the eight research areas. A new field is linked into its area&#39;s chain with a <code>splice</code> patch row after the field it follows.</p><p>A mod adds records in <code>records/tech-fields/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;tech-fields&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>tech-fields</code>. Schema: <a href="/carina-mod-template/schemas/records/tech-fields.schema.json">tech-fields records schema</a>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-kind" class="field-name"><code>kind</code></span><a class="field-link" href="#f-kind" aria-label="Link to kind">#</a></td><td>one of <code>starting</code>, <code>normal</code>, <code>xenon</code>, <code>hyperAdvanced</code></td><td>yes</td><td></td></tr><tr><td><span id="f-area" class="field-name"><code>area</code></span><a class="field-link" href="#f-area" aria-label="Link to area">#</a></td><td>one of <code>biology</code>, <code>chemistry</code>, <code>computers</code>, <code>construction</code>, <code>forceFields</code>, <code>physics</code>, <code>power</code>, <code>sociology</code> or null</td><td>yes</td><td>the research area the field belongs to</td></tr><tr><td><span id="f-prev" class="field-name"><code>prev</code></span><a class="field-link" href="#f-prev" aria-label="Link to prev">#</a></td><td>key of a record in <code>tech-fields</code>, or null</td><td>yes</td><td>the field before it (written by the splice row; null in the record)</td></tr><tr><td><span id="f-next" class="field-name"><code>next</code></span><a class="field-link" href="#f-next" aria-label="Link to next">#</a></td><td>key of a record in <code>tech-fields</code>, or null</td><td>yes</td><td>the field after it (written by the splice row; null in the record)</td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>integer &gt;= 0</td><td>yes</td><td>research points to learn the field</td></tr><tr><td><span id="f-level" class="field-name"><code>level</code></span><a class="field-link" href="#f-level" aria-label="Link to level">#</a></td><td>integer 0..22</td><td>yes</td><td>the field&#39;s place in its area; between the neighbours it is spliced between</td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr></tbody></table><p>References to other records are written as keys; the game turns them into ids.</p><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>patches: a <code>splice</code> row (<code>key</code> = your field, <code>after</code> = the field it follows) links it into the chain; its <code>level</code> must lie between its neighbours&#39;</li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>The computer players research a new field like any other; they value it by the <code>aiGroup</code> of its applications.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Eight research areas, no ninth area.</li><li>Only <code>normal</code> fields join a chain, and never after the chain&#39;s hyper-advanced end (<code>splice-end</code>).</li><li>Write <code>prev</code> and <code>next</code> as null in the record; the splice row sets them.</li><li><code>level</code> is 0 to 22 (the research value tables).</li><li>A <code>remove</code> row takes a normal base field out of its chain; its neighbours link to each other. Its applications and everything naming them must go too: the compile lists them (<code>removed-dependent</code>). Starting, Xenon and hyper-advanced fields are not removed.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>area</code>, <code>cost</code>, <code>kind</code>, <code>level</code>, <code>nameKey</code>, <code>next</code>, <code>prev</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: none (no list fields)</li></ul>',16)])])}const m=t(c,[["render",i]]);export{p as __pageData,m as default};
